checks={'carrier_PL':'PL_Alexander_composite' in cap and '(1-r)e_j' in cap,'carrier_saturated':'unimodular' in cap,'multirees_regular':'multi_Rees_ring' in cap and 'regular' in cap,'offdiagonal_typed':'Verdier_off_diagonal' in cap and '[t_i]epsilon_i' in cap,'anticommutes':'anticommutes' in cap,'not_spatial':'spatial_correspondence_to_H_Sigma_e_F_Q' in cap and 'false' in cap,'first_flip':'de=X_D03*m_plus-x5*v_plus' in flip,'primitive_syzygy':'(x5,X_D03)' in flip,'scalar_falsified':'scalar_1_1' in flip and 'FALSIFIED' in flip,'normal_separate':'u5^vee' in flip and 'cannot substitute' in flip,'literal_missing':'marked spatial identification with the literal entry143 edge' in flip}
assert all(checks.values()),checks
out={'schema':'marici.voevodsky.CR1-marked-spatial-multi-Rees-correspondence.v1','prospective_action':'CR1A1a1i1a1a2i1a1a2b1a1a1a_construct_marked_spatial_multi_Rees_correspondence','outcome_contract':{'++':'one marked spatial pull-push is constructed and its D3 orbit gives the full 1-r BC map','+-':'the unique coefficient/carrier tensor and primitive first-flip line are fixed, but spatial identification is absent','-+':'the first-flip line is nonsaturated or incompatible with PL','--':'no typed candidate exists'},'resolution':'+-','proved':{'carrier_map':'1-r, saturated','coefficient_off_diagonal':'[t_i] epsilon_i','total_bicomplex':'square-zero and anticommuting','first_flip_complex':'de=X_D03 m_plus-x5 v_plus','primitive_closed_functional':['x5','X_D03'],'scalar_functional':'impossible'},'typing_warning':'u5^vee is a normal dual and cannot replace either occurrence-ideal dual.','remaining':'Construct the marked spatial identification of this primitive first-flip line with the literal entry143 edge and extraordinary filtered-Q leg.','refinement':['CR1A1a1i1a1a2i1a1a2b1a1a1a1_construct_first_flip_spatial_pull_push'],'next':'Construct one spatial D03 first-flip pull-push; only then take its D3 orbit.','checks':checks,'passed':True};p=R/'research/voevodsky/results/CR1_marked_spatial_multi_Rees_correspondence.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'resolution':'+-','primitive_first_flip':['x5','X_D03'],'spatial':False,'next':out['refinement'][0]}))
